  s := pg_get_serial_sequence('public.ksa_country_upload_template', 'id');
  execute format('REVOKE ALL ON SEQUENCE %s FROM PUBLIC, anon, authenticated, service_role', s);
  execute format('GRANT SELECT, UPDATE, USAGE ON SEQUENCE %s TO authenticated', s);
